cd /dateutil && python - <<'EOF'
# Compare the pyc-compiled parser module (from an earlier state?) with source
import marshal
d=open('dateutil/__pycache__/parser.cpython-36.pyc','rb').read()
code=marshal.loads(d[12:])
def find(code, name, path=()):
    for c in code.co_consts:
        if hasattr(c,'co_name'):
            if c.co_name==name:
                yield path+(c.co_name,), c
            yield from find(c, name, path+(c.co_name,))
src=open('dateutil/parser.py').read()
mod=compile(src,'x','exec')
for p,c in find(code,'_parse'):
    for p2,c2 in find(mod,'_parse'):
        print(p, p2, c.co_code==c2.co_code)
        break
    break
# also check _timelex
for p,c in find(code,'_timelex'):
    for p2,c2 in find(mod,'_timelex'):
        print(p, p2, c.co_code==c2.co_code)
        break
    break
EOF

